// Generated by Viscosity: "ps" stored as a struct of arrays (fields x, name).
class __Vsc_ps {
  constructor(cap = 16) { this.length = 0; this.cap = cap; this.x = new Float64Array(cap); this.name = []; }
  static of(...v) { const c = new __Vsc_ps(Math.max(16, v.length / 2)); for (let i = 0; i < v.length; i += 2) c.push(v[i + 0], v[i + 1]); return c; }
  push(v0, v1) { const n = this.length; if (n === this.cap) this.grow(); this.x[n] = v0; this.name[n] = v1; return (this.length = n + 1); }
  grow() { const cap = (this.cap *= 2); let t; t = new Float64Array(cap); t.set(this.x); this.x = t; }
}
